// src/notify-linux.ts
var DESTINATION = "org.freedesktop.Notifications";
var PATH = "/org/freedesktop/Notifications";
var CALL_TIMEOUT_MS = 2000;
var MAX_ACTIONS = 128;
var connection;
var current;
var generation = 0;
var lastID = 0;
var queue = Promise.resolve();
function getLinuxNotificationID() {
  return lastID || null;
}
function rememberLinuxNotificationID(id) {
  lastID = id;
  current?.callbacks.delete(id);
}
function debug(message) {
  if (process.env.OPENCODE_NOTIFIER_DEBUG)
    console.error(`[opencode-notifier] ${message}`);
}
function bounded(operation) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("notification D-Bus call timed out")), CALL_TIMEOUT_MS);
    timer.unref();
    operation.then(resolve, reject).finally(() => clearTimeout(timer));
  });
}
function resetConnection() {
  connection = undefined;
  const old = current;
  current = undefined;
  lastID = 0;
  old?.callbacks.clear();
  old?.fail(new Error("notification connection closed"));
  try {
    old?.bus.disconnect();
  } catch {}
}
function disposeLinuxNotifications() {
  generation++;
  resetConnection();
}
function handleSignal(state, member, id, value) {
  if (member === "NotificationClosed")
    state.callbacks.delete(id);
  if (member === "ActionInvoked" && value === "focus-terminal") {
    const callback = state.callbacks.get(id);
    state.callbacks.delete(id);
    try {
      callback?.();
    } catch {}
  }
}
async function connect() {
  const epoch = generation;
  const dbus = (await import("@particle/dbus-next")).default;
  if (epoch !== generation)
    throw new Error("notification channel disposed");
  const bus = dbus.sessionBus();
  let fail;
  const failure = new Promise((_resolve, reject) => {
    fail = reject;
  });
  failure.catch(() => {
    return;
  });
  const state = { bus, owner: "", callbacks: new Map, pendingSignals: null, failure, fail };
  current = state;
  bus.on("error", (error) => {
    debug(`notification D-Bus error: ${String(error)}`);
    if (current === state)
      resetConnection();
  });
  const stream = bus._connection?.stream;
  state.stream = stream;
  stream?.on?.("close", () => {
    if (current === state)
      resetConnection();
  });
  bus.on("message", (message) => {
    if (message.type !== dbus.MessageType.SIGNAL)
      return;
    if (message.sender === "org.freedesktop.DBus" && message.interface === "org.freedesktop.DBus" && message.member === "NameOwnerChanged" && message.body[0] === DESTINATION) {
      state.owner = message.body[2];
      state.callbacks.clear();
      lastID = 0;
      return;
    }
    if (message.sender !== state.owner || message.path !== PATH || message.interface !== DESTINATION)
      return;
    const [id, value] = message.body;
    if (state.pendingSignals)
      state.pendingSignals.push([message.member, id, value]);
    else
      handleSignal(state, message.member, id, value);
  });
  for (const rule of [
    `type='signal',sender='${DESTINATION}',path='${PATH}',interface='${DESTINATION}'`,
    `type='signal',sender='org.freedesktop.DBus',interface='org.freedesktop.DBus',member='NameOwnerChanged',arg0='${DESTINATION}'`
  ]) {
    await bounded(Promise.race([failure, bus.call(new dbus.Message({
      destination: "org.freedesktop.DBus",
      path: "/org/freedesktop/DBus",
      interface: "org.freedesktop.DBus",
      member: "AddMatch",
      signature: "s",
      body: [rule]
    }))]));
  }
  try {
    const reply = await bounded(Promise.race([failure, bus.call(new dbus.Message({
      destination: "org.freedesktop.DBus",
      path: "/org/freedesktop/DBus",
      interface: "org.freedesktop.DBus",
      member: "GetNameOwner",
      signature: "s",
      body: [DESTINATION]
    }))]));
    state.owner = reply?.body[0] ?? "";
  } catch (error) {
    if (error.type !== "org.freedesktop.DBus.Error.NameHasNoOwner")
      throw error;
  }
  if (current !== state || epoch !== generation)
    throw new Error("notification connection closed");
  return state;
}
function sendLinuxActionNotification(title, message, timeout, iconPath, grouping, onClick, label) {
  const epoch = generation;
  const operation = queue.then(async () => {
    if (epoch !== generation)
      return true;
    let state;
    try {
      state = await (connection ??= connect());
      if (current !== state)
        return true;
      state.stream?.ref?.();
      const dbus = (await import("@particle/dbus-next")).default;
      if (state.callbacks.size >= MAX_ACTIONS && !(grouping && state.callbacks.has(lastID))) {
        const id = state.callbacks.keys().next().value;
        await bounded(Promise.race([state.failure, state.bus.call(new dbus.Message({
          destination: DESTINATION,
          path: PATH,
          interface: DESTINATION,
          member: "CloseNotification",
          signature: "u",
          body: [id]
        }))]));
        state.callbacks.delete(id);
      }
      state.pendingSignals = [];
      const reply = await bounded(Promise.race([state.failure, state.bus.call(new dbus.Message({
        destination: DESTINATION,
        path: PATH,
        interface: DESTINATION,
        member: "Notify",
        signature: "susssasa{sv}i",
        body: [
          "opencode",
          grouping ? lastID : 0,
          iconPath ?? "",
          title,
          message,
          ["focus-terminal", label],
          {},
          Math.max(1, timeout) * 1000
        ]
      }))]));
      if (current !== state || epoch !== generation)
        return true;
      if (reply?.sender)
        state.owner = reply.sender;
      const id = reply?.body[0];
      if (!Number.isInteger(id) || id <= 0)
        throw new Error("invalid notification ID");
      if (grouping)
        lastID = id;
      state.callbacks.set(id, onClick);
      const signals = state.pendingSignals;
      state.pendingSignals = null;
      for (const [member, signalID, value] of signals ?? [])
        handleSignal(state, member, signalID, value);
      return true;
    } catch (error) {
      if (epoch !== generation)
        return true;
      debug(`persistent notification failed: ${String(error)}`);
      if (!state || current === state)
        resetConnection();
      return false;
    } finally {
      state?.stream?.unref?.();
    }
  });
  queue = operation.catch(() => {
    return;
  });
  return operation;
}

