import { chmodSync, statSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
function debug2(message) {
  if (process.env.OPENCODE_NOTIFIER_DEBUG)
    console.error(`[opencode-notifier] snoreToast: ${message}`);
}
function ensureSnoreToastExecutable() {
  try {
    const root = dirname(createRequire(import.meta.url).resolve("node-notifier"));
    const path = join(root, "vendor", "snoreToast", `snoretoast-x${process.arch === "x64" ? "64" : "86"}.exe`);
    const { mode } = statSync(path);
    if (mode & 64)
      return;
    chmodSync(path, mode | 73);
    debug2(`restored +x on ${path}`);
  } catch (error) {
    debug2(`could not restore +x: ${String(error)}`);
  }
}

// src/notify-windows.ts
import { execFile } from "child_process";
import { pathToFileURL } from "url";
var REMINDER_ACTIONS = '<actions><action content="Dismiss" arguments="dismiss" activationType="background"/></actions>';
var POWERSHELL_TIMEOUT_MS = 2000;
var WINDOWS_TOAST_DISPLAY_NAME = "OpenCode";
function debug3(message) {
  if (process.env.OPENCODE_NOTIFIER_DEBUG)
    console.error(`[opencode-notifier] ${message}`);
}
function escapeXml(value) {
  return value.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\uFFFE\uFFFF]/g, "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}
function toWindowsDrivePath(value, wsl) {
  const normalized = value.replace(/\\/g, "/");
  const drive = normalized.match(/^([A-Za-z]):\/(.*)$/);
  if (drive)
    return `${drive[1].toUpperCase()}:/${drive[2]}`;
  const wslDrive = normalized.match(/^\/mnt\/([a-z])\/(.*)$/i);
  if (wsl && wslDrive)
    return `${wslDrive[1].toUpperCase()}:/${wslDrive[2]}`;
  return null;
}
function toWindowsFileUri(iconPath, wsl) {
  const value = iconPath?.trim();
  if (!value)
    return null;
  const drivePath = toWindowsDrivePath(value, wsl);
  if (drivePath) {
    const [drive, ...segments] = drivePath.split("/");
    return `file:///${drive}/${segments.map((segment) => encodeURIComponent(segment)).join("/")}`;
  }
  if (!wsl && value.replace(/\\/g, "/").startsWith("/")) {
    try {
      return pathToFileURL(value).href;
    } catch {
      return null;
    }
  }
  return null;
}
function toWindowsIconPath(iconPath, wsl) {
  const value = iconPath?.trim();
  if (!value)
    return null;
  const drivePath = toWindowsDrivePath(value, wsl);
  if (drivePath)
    return drivePath;
  if (!wsl && value.replace(/\\/g, "/").startsWith("/"))
    return value;
  return null;
}
function buildWindowsToastXml(title, message, iconUri, scenario) {
  const image = iconUri ? `<image placement="appLogoOverride" hint-crop="none" src="${escapeXml(iconUri)}"/>` : "";
  const scenarioAttribute = scenario === "default" ? "" : ` scenario="${scenario}"`;
  const actions = scenario === "reminder" ? REMINDER_ACTIONS : "";
  return `<toast${scenarioAttribute}><visual><binding template="ToastGeneric"><text>${escapeXml(title)}</text><text>${escapeXml(message)}</text>${image}</binding></visual>${actions}</toast>`;
}
function buildWindowsToastPayload(request, scenario) {
  return {
    appId: request.appID,
    displayName: WINDOWS_TOAST_DISPLAY_NAME,
    iconPath: toWindowsIconPath(request.iconPath, request.wsl),
    xml: buildWindowsToastXml(request.title, request.message, toWindowsFileUri(request.iconPath, request.wsl), scenario)
  };
}
function buildWindowsToastScript(payload) {
  const encoded = Buffer.from(JSON.stringify(payload), "utf8").toString("base64");
  return `$ErrorActionPreference = 'Stop'
$payload = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('${encoded}')) | ConvertFrom-Json
$appKey = "HKCU:\\Software\\Classes\\AppUserModelId\\$($payload.appId)"
$registered = Get-ItemProperty -Path $appKey -ErrorAction SilentlyContinue
$needsIcon = $payload.iconPath -and ($null -eq $registered -or $registered.IconUri -ne $payload.iconPath)
$staleIcon = -not $payload.iconPath -and $null -ne $registered -and $null -ne $registered.IconUri
if ($null -eq $registered -or $registered.DisplayName -ne $payload.displayName -or $needsIcon -or $staleIcon) {
  New-Item -Path $appKey -Force | Out-Null
  Set-ItemProperty -Path $appKey -Name DisplayName -Value $payload.displayName
  if ($payload.iconPath) {
    Set-ItemProperty -Path $appKey -Name IconUri -Value $payload.iconPath
  } elseif ($staleIcon) {
    Remove-ItemProperty -Path $appKey -Name IconUri
  }
}
[Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime] | Out-Null
[Windows.Data.Xml.Dom.XmlDocument, Windows.Data.Xml.Dom, ContentType = WindowsRuntime] | Out-Null
$xml = New-Object Windows.Data.Xml.Dom.XmlDocument
$xml.LoadXml($payload.xml)
$toast = [Windows.UI.Notifications.ToastNotification]::new($xml)
[Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier($payload.appId).Show($toast)`;
}
function sendWindowsReminderNotification(request) {
  const payload = buildWindowsToastPayload(request, "reminder");
  const script = buildWindowsToastScript(payload);
  const encoded = Buffer.from(script, "utf16le").toString("base64");
  const command = request.wsl ? "powershell.exe" : "powershell";
  return new Promise((resolve) => {
    execFile(command, ["-NoProfile", "-NonInteractive", "-EncodedCommand", encoded], { timeout: POWERSHELL_TIMEOUT_MS, windowsHide: true }, (error) => {
      if (error)
        debug3(`reminder toast failed: ${String(error)}`);
      resolve(!error);
    });
  });
}
async function deliverWindowsNotification(scenario, request, sendDefault) {
  if (scenario === "reminder" && await sendWindowsReminderNotification(request))
    return;
  await sendDefault();
